package co.elhacker.maquinitas.servlet;
import co.elhacker.maquinitas.dao.TiendaDAO;import co.elhacker.maquinitas.util.*;import jakarta.servlet.ServletException;import jakarta.servlet.annotation.*;import jakarta.servlet.http.*;import java.io.*;import java.math.BigDecimal;import java.nio.file.*;import java.util.*;
@WebServlet("/recargas") @MultipartConfig(maxFileSize=5*1024*1024, maxRequestSize=6*1024*1024)
public class RecargasServlet extends HttpServlet {private final TiendaDAO dao=new TiendaDAO();
 protected void doGet(HttpServletRequest q,HttpServletResponse r)throws IOException{Integer u=Autenticacion.usuario(q);if(u==null){Json.enviar(r,401,Map.of("success",false,"message","Inicia sesión."));return;}try{Json.enviar(r,200,Map.of("success",true,"recargas",Autenticacion.admin(q)?dao.todasRecargas():dao.recargasUsuario(u)));}catch(Exception e){getServletContext().log("Error recargas",e);Json.enviar(r,500,Map.of("success",false,"message","No se pudieron consultar las recargas."));}}
 protected void doPost(HttpServletRequest q,HttpServletResponse r)throws IOException,ServletException{Integer u=Autenticacion.usuario(q);if(u==null){Json.enviar(r,401,Map.of("success",false,"message","Inicia sesión."));return;}if(Autenticacion.admin(q)){try{long id=Long.parseLong(q.getParameter("id_recarga"));String estado=q.getParameter("estado");dao.resolverRecarga(id,u,estado,q.getParameter("notas_admin"));Json.enviar(r,200,Map.of("success",true,"message","Recarga revisada correctamente."));}catch(IllegalArgumentException e){Json.enviar(r,400,Map.of("success",false,"message",e.getMessage()));}catch(Exception e){getServletContext().log("Error aprobando recarga",e);Json.enviar(r,500,Map.of("success",false,"message","No se pudo revisar la recarga."));}return;}
 String archivo=null;try{BigDecimal monto=new BigDecimal(q.getParameter("monto_usdt"));String tx=q.getParameter("tx_hash");if(tx==null||tx.trim().length()<8||tx.length()>180)throw new IllegalArgumentException("Ingresa el identificador de la transacción de Binance.");Part file=q.getPart("comprobante");if(file!=null&&file.getSize()>0){String type=file.getContentType();if(!Set.of("image/jpeg","image/png","application/pdf").contains(type))throw new IllegalArgumentException("El comprobante debe ser JPG, PNG o PDF.");String ext=type.equals("image/jpeg")?".jpg":type.equals("image/png")?".png":".pdf";String name=UUID.randomUUID()+ext;String base=System.getProperty("catalina.base",System.getProperty("java.io.tmpdir"));Path dir=Paths.get(base,"uploads","hacker-comprobantes");Files.createDirectories(dir);try(InputStream in=file.getInputStream()){Files.copy(in,dir.resolve(name));}archivo=name;}long id=dao.crearRecarga(u,monto,tx.trim(),archivo);Json.enviar(r,201,Map.of("success",true,"id_recarga",id,"message","Solicitud enviada. El saldo se acredita cuando el administrador la apruebe."));}catch(IllegalArgumentException e){Json.enviar(r,400,Map.of("success",false,"message",e.getMessage()));}catch(Exception e){getServletContext().log("Error creando recarga",e);Json.enviar(r,500,Map.of("success",false,"message","No se pudo registrar la solicitud de recarga."));}}
}
